<script setup>
import {computed,onMounted,onUnmounted,ref,watch,nextTick} from 'vue';
import api from '@/sheep/api/pharmacy/server';
import {money,normalizeDrug,formatDate} from '@/sheep/api/pharmacy/common';
import {createStreamController} from '@/sheep/api/pharmacy/sse';
import {identity,clearLoginState} from './session.js';
import {sameIdentity} from './guards.js';
import {localTestLogin} from './config.js';
import ProductCard from './ProductCard.vue';
import LoginGate from '#test-login';
import RegisterGate from '#test-register';
import AccountPage from './AccountPage.vue';
import account from './account.js';
import TradePages from './TradePages.vue';
import SearchSuggestions from './SearchSuggestions.vue';
import trade from './trade.js';
const route=ref('catalog'),routeOrderId=ref(''),adding=ref(false),query=ref(''),category=ref('all'),page=ref(1),items=ref([]),categories=ref([]),count=ref(0),catalogLoading=ref(false),catalogError=ref(''),detail=ref(null),detailLoading=ref(false),detailError=ref(''),infoTab=ref('info'),storeName=ref('正在读取门店…');
const authScreen=ref('login');
const suggestionBox=ref(null);
const user=ref(null),authReady=ref(false),authBusy=ref(false),loginOpen=ref(false),dialog=ref(''),toastText=ref('');
const topics=ref([]),moreTopics=ref(false),historyLoading=ref(false),historyError=ref(''),historyOpen=ref(false),topicId=ref(null),topicStore=ref(null),moreTurns=ref(false),messages=ref([]),input=ref(''),busy=ref(false),chatScroll=ref(null),stockWarning=ref(false);
let disposed=false,generation=0,controller,active,typingTimer,toastTimer,publicGeneration=0;
const isTrade=computed(()=>['cart','checkout','orders','order-detail'].includes(route.value));
const authName=computed(()=>user.value?.name||'会员');
const currentOwner=()=>JSON.stringify(identity());
const newId=()=>`consult_${Date.now()}_${crypto.randomUUID().slice(0,8)}`;
function notify(t){toastText.value=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastText.value='',3500);}
function go(hash){if(location.hash==='#'+hash)parseRoute();else location.hash=hash;}
function notConnected(name){dialog.value=`${name}尚未接入。本轮已开放登录、AI、商品、购物车与普通订单。`;}
function stop(){generation++;historyLoading.value=false;controller?.abort();clearTimeout(typingTimer);typingTimer=null;if(active?.loading){active.loading=false;active.status='STOPPED';active.error='已停止接收回复；请求可能仍在处理，稍后可重载话题查看结果。';}busy.value=false;}
function resetPrivate(){closeSuggestions();stop();trade.reset();adding.value=false;if(location.hash.startsWith('#ai?'))history.replaceState(null,'','#ai');messages.value=[];topics.value=[];topicId.value=null;topicStore.value=null;moreTurns.value=false;moreTopics.value=false;historyError.value='';historyLoading.value=false;input.value='';user.value=null;historyOpen.value=false;dialog.value='';}
function authCleared(){resetPrivate();authReady.value=true;}
async function logout(){if(authBusy.value)return;authBusy.value=true;resetPrivate();try{await account.logout();}finally{authBusy.value=false;}notify('已退出登录');}
// Credentials are user supplied and never stored by the application.
async function onLoggedIn(profile){if(disposed)return;user.value=profile;loginOpen.value=false;authScreen.value='login';notify('登录成功');if(route.value==='ai')await loadTopics();else if(route.value==='catalog')loadCatalog();}
async function loadCatalog(){const g=++publicGeneration;catalogLoading.value=true;catalogError.value='';stockWarning.value=false;try{const [list,result]=await Promise.all([api.loadCategories(),api.productPage({keyword:query.value,category:category.value,pageNo:page.value,pageSize:9})]);if(g!==publicGeneration)return;categories.value=list;items.value=result.list;count.value=result.total;storeName.value=api.store.name;}catch(e){if(g===publicGeneration){catalogError.value=e.message;items.value=[];}}finally{if(g===publicGeneration)catalogLoading.value=false;}}
async function loadDetail(id){const g=++publicGeneration;detail.value=null;detailLoading.value=true;detailError.value='';infoTab.value='info';stockWarning.value=false;try{if(!/^\d+$/.test(id||''))throw Error('商品链接无效');const p=await api.product(id);if(g!==publicGeneration)return;detail.value=p;storeName.value=api.store.name;}catch(e){if(g===publicGeneration)detailError.value=e.message;}finally{if(g===publicGeneration)detailLoading.value=false;}}
function closeSuggestions(){suggestionBox.value?.close();}
function search(){closeSuggestions();page.value=1;loadCatalog();}
function selectSearchProduct(id){go('detail?id='+id);}
function pickCategory(id){category.value=id;page.value=1;loadCatalog();}
function paginate(n){page.value=n;loadCatalog();window.scrollTo(0,0);}
function aiProducts(rows=[]){return rows.map(p=>normalizeDrug({id:p.id,tradeName:p.name,genericName:p.genericName,specification:p.specification,manufacturer:p.manufacturer,isRx:0,memberPrice:p.price},{stock:p.availableQty,image:p.imageUrl,approval:p.approvalNo}));}
function restored(t){const r=t.response,status=r?.status||'PENDING';return{id:t.clientMessageId,recordId:t.id,content:t.content,context:[],answer:r?.answer||'',products:aiProducts(r?.products),status,source:r?.source,queriedAt:formatDate(r?.queriedAt),loading:false,error:status==='FAILED'?'本次回复未完成，可重新提问。':status==='PENDING'?'请求可能仍在处理，请稍后重载话题。':''};}
async function loadTopics(append=false){append=append===true;if(!user.value)return;const owner=currentOwner(),g=generation;historyLoading.value=true;historyError.value='';try{const rows=await api.aiTopics(append?topics.value.at(-1)?.id:undefined);if(owner!==currentOwner()||g!==generation)return;topics.value=append?[...topics.value,...rows]:rows;moreTopics.value=rows.length===30;}catch(e){if(owner===currentOwner()&&g===generation)historyError.value=e.message;}finally{if(owner===currentOwner()&&g===generation)historyLoading.value=false;}}
async function openTopic(id,earlier=false){if(!user.value)return;stop();const owner=currentOwner(),g=generation;historyLoading.value=true;historyError.value='';if(!earlier){messages.value=[];topicId.value=null;topicStore.value=null;}try{const d=await api.aiTopic(id,earlier?messages.value[0]?.recordId:undefined);if(owner!==currentOwner()||g!==generation)return;const rows=d.turns.map(restored);messages.value=earlier?[...rows,...messages.value]:rows;topicId.value=d.topic.id;topicStore.value=d.topic.storeId;moreTurns.value=d.hasMore;historyOpen.value=false;history.replaceState(null,'',`#ai?topic=${d.topic.id}`);}catch(e){if(owner===currentOwner()&&g===generation)historyError.value=e.message;}finally{if(owner===currentOwner()&&g===generation)historyLoading.value=false;}}
async function newTopic(){if(!user.value){loginOpen.value=true;return;}if(historyLoading.value)return;stop();messages.value=[];topicId.value=null;topicStore.value=null;input.value='';moreTurns.value=false;history.replaceState(null,'','#ai');const owner=currentOwner(),g=generation;historyLoading.value=true;try{const t=await api.createAiTopic();if(owner!==currentOwner()||g!==generation)return;topicId.value=t.id;topicStore.value=t.storeId;topics.value=[t,...topics.value];history.replaceState(null,'',`#ai?topic=${t.id}`);historyOpen.value=false;}catch(e){if(owner===currentOwner()&&g===generation)historyError.value=e.message;}finally{if(owner===currentOwner()&&g===generation)historyLoading.value=false;}}
async function queryAI(message){if(busy.value||historyLoading.value||!user.value)return;const owner=currentOwner(),g=generation;const current=()=>g===generation&&owner===currentOwner()&&!!user.value;controller=createStreamController();const signal=controller.signal;active=message;busy.value=true;message.loading=true;message.error='';message.answer='';message.products=[];const queue=[];const type=()=>{if(!current()||signal.aborted)return;message.answer+=queue.splice(0,4).join('');typingTimer=queue.length?setTimeout(type,20):null;};try{if(!topicId.value){const t=await api.createAiTopic();if(!current()||signal.aborted)return;topicId.value=t.id;topicStore.value=t.storeId;history.replaceState(null,'',`#ai?topic=${t.id}`);}const result=await api.consultStream({clientMessageId:message.id,content:message.content,context:message.context,topicId:topicId.value,storeId:topicStore.value},(event,data)=>{if(!current()||signal.aborted)return;if(event==='delta'){queue.push(...Array.from(data.text||''));if(!typingTimer)type();}},signal);if(!current()||signal.aborted)return;if(result.status==='FAILED'){clearTimeout(typingTimer);typingTimer=null;message.answer+=queue.splice(0).join('');}else while(queue.length&&current()&&!signal.aborted)await new Promise(r=>setTimeout(r,20));if(!current()||signal.aborted)return;message.status=result.status;if(result.status!=='FAILED'||!message.answer||result.answer?.startsWith(message.answer))message.answer=result.answer||message.answer;message.error=result.status==='FAILED'?'本次回复未完成，请重试。':'';message.products=aiProducts(result.products);message.source=result.source;message.queriedAt=formatDate(result.queriedAt);}catch(e){if(!current())return;message.answer+=queue.splice(0).join('');message.status='NETWORK_ERROR';message.error=e.message||'回复中断，请重试';}finally{if(current()){clearTimeout(typingTimer);typingTimer=null;message.loading=false;busy.value=false;loadTopics();}}}
function send(text=input.value){if(busy.value||historyLoading.value||!text.trim())return;if(!user.value){loginOpen.value=true;return;}const context=messages.value.filter(m=>m.status==='SUCCESS').flatMap(m=>[{role:'user',content:m.content},{role:'assistant',content:m.answer.slice(0,1000)}]).slice(-6);messages.value.push({id:newId(),content:text.trim().slice(0,500),context,answer:'',products:[],loading:true});input.value='';queryAI(messages.value.at(-1));}
function retry(m){if(m.status==='FAILED')m.id=newId();queryAI(m);}
function askProduct(){const p=detail.value;go('ai');nextTick(()=>input.value=`查询${p.genericName||p.name}的价格和库存`);}
function parseRoute(){closeSuggestions();const [key,qs]=location.hash.slice(1).split('?'),params=new URLSearchParams(qs);const next=['ai','catalog','detail','cart','checkout','orders','order-detail','account'].includes(key)?key:'catalog';if(route.value==='ai'&&next!=='ai')stop();route.value=next;routeOrderId.value=params.get('id')||'';document.body.dataset.page=next;window.scrollTo(0,0);if(next==='catalog')loadCatalog();else if(next==='detail')loadDetail(params.get('id'));else if(next==='ai'&&user.value){if(params.get('topic')&&String(topicId.value)!==params.get('topic'))openTopic(params.get('topic'));else loadTopics();}}
async function addToCart(p){if(!user.value){loginOpen.value=true;return;}if(adding.value)return;const owner=identity();adding.value=true;try{if(!api.store.id)throw Error('请先读取门店商品');await trade.add(api.store.id,p,1);if(sameIdentity(owner,identity()))notify('已加入当前门店购物车');}catch(e){if(sameIdentity(owner,identity()))dialog.value=e.message;}finally{if(sameIdentity(owner,identity()))adding.value=false;}}
let backdropStarted=false,backdropEnded=false,backdropPointer;
function closeDialog(){backdropStarted=false;backdropEnded=false;loginOpen.value=false;dialog.value='';}
function backdropDown(event){backdropEnded=false;backdropStarted=event.target===event.currentTarget&&(event.button==null||event.button===0)&&event.isPrimary!==false;backdropPointer=event.pointerId;}
function backdropUp(event){backdropEnded=event.target===event.currentTarget&&(event.pointerId==null||backdropPointer==null||event.pointerId===backdropPointer);}
function backdropCancel(){backdropStarted=false;backdropEnded=false;}
function backdropClick(event){const close=backdropStarted&&backdropEnded&&event.target===event.currentTarget&&(event.pointerId==null||backdropPointer==null||event.pointerId===backdropPointer);backdropStarted=false;if(close)closeDialog();}
function stockFailed(){stockWarning.value=true;}
watch(()=>messages.value.map(m=>m.answer+m.error).join(''),async()=>{const el=chatScroll.value;if(!el)return;const near=el.scrollHeight-el.scrollTop-el.clientHeight<160;await nextTick();if(near)el.scrollTop=el.scrollHeight;});
onMounted(async()=>{
 window.addEventListener('hashchange',parseRoute);window.addEventListener('firstsun-auth-clear',authCleared);window.addEventListener('firstsun-stock-error',stockFailed);parseRoute();
 const owner=identity(),current=()=>!disposed&&sameIdentity(owner,identity());
 try{if(api.session()){const profile=await api.profile();if(current())user.value=profile;}}
 catch{if(current())clearLoginState();}
 if(disposed)return;
 authReady.value=true;if(current()&&route.value==='ai'&&user.value)parseRoute();
});
onUnmounted(()=>{disposed=true;stop();clearTimeout(toastTimer);window.removeEventListener('hashchange',parseRoute);window.removeEventListener('firstsun-auth-clear',authCleared);window.removeEventListener('firstsun-stock-error',stockFailed);});
</script>
<template>
<header id="header"><a class="brand" href="#catalog"><span class="wordmark">FirstSun<span class="brand-dot">.</span></span><span class="brand-sub">网上药房</span></a><nav class="nav" aria-label="全局导航"><a href="#catalog" :class="{active:route==='catalog'||route==='detail'}">找药购药</a><a href="#ai" class="ai-nav" :class="{active:route==='ai'}"><Icon name="sparkles"/>AI 助手<span class="nav-ai-label">AI</span></a><button @click="notConnected('我的处方')">我的处方</button><a href="#orders" :class="{active:route==='orders'||route==='order-detail'}">我的订单</a></nav><div class="header-tools"><span class="prototype" v-if="localTestLogin">独立本机验收</span><button class="tool" aria-label="消息中心" @click="notConnected('消息中心')"><Icon name="bell"/></button><button class="tool cart-tool" @click="go('cart')"><Icon name="shopping-bag"/><span class="label">购物车</span></button><button v-if="!user" class="tool auth-entry" :disabled="authBusy" @click="loginOpen=true"><Icon name="circle-user-round"/><span>登录</span></button><button v-else class="tool auth-entry" @click="go('account')" aria-label="个人中心"><img v-if="user.avatar" :src="user.avatar" alt="" style="width:28px;height:28px;border-radius:50%;object-fit:cover"><Icon v-else name="circle-user-round"/><span>{{authName}}</span></button></div></header>
<AccountPage v-if="route==='account'" :key="user?.userId||'guest'" :user="user" @profile="user=$event" @logout="logout" @login="loginOpen=true"/><TradePages v-else-if="isTrade" :key="route+':'+routeOrderId+':'+(user?.userId||'guest')" :route="route" :order-id="routeOrderId" :user="user" @login="loginOpen=true" @notice="notify"/><main v-else-if="route==='catalog'" class="shop-page"><section class="shop-search"><div><span class="shop-kicker">FIRSTSUN · 网上药房</span><h1>你需要的药，在这里找。</h1><span class="live-store">{{storeName}}</span></div><div class="search-area"><SearchSuggestions ref="suggestionBox" v-model="query" :category="category" :store-id="api.store.id" :loading="catalogLoading" @search="search" @select="selectSearchProduct"/><div class="search-shortcuts"><span>按药品名称检索 · 价格与库存由当前门店返回</span></div></div></section><section class="shop-services"><a class="ai-entry" href="#ai"><div class="service-symbol"><Icon name="sparkles"/></div><div class="grow"><div class="entry-eyebrow">FIRSTSUN AI</div><h2>找药有疑问？问问 AI</h2><p>查商品 · 看规格 · 了解购药流程</p></div><span class="entry-arrow"><Icon name="arrow-up-right"/></span></a><button class="shop-service" @click="notConnected('处方申请')"><span class="service-symbol"><Icon name="file-check-2"/></span><span class="grow"><strong>处方购药</strong><span>需经药师审核 · 本批未接入</span></span></button><button class="shop-service" @click="notConnected('药师 / 客服咨询')"><span class="service-symbol"><Icon name="headset"/></span><span class="grow"><strong>咨询药师 / 客服</strong><span>人工服务 · 本批未接入</span></span></button></section><nav class="shop-categories" aria-label="商品分类"><button v-for="c in categories" :key="c.id" class="category-btn" :class="{active:category===c.id}" :aria-pressed="category===c.id" @click="pickCategory(c.id)"><span><Icon name="pill"/></span>{{c.name}}</button></nav><section class="shop-products"><div class="shop-section-heading"><div><h2>{{query?'搜索结果':'全部商品'}}</h2><span>核对商品信息，自主选择</span></div><a href="#ai"><Icon name="sparkles"/>让 AI 帮我找<Icon name="arrow-up-right"/></a></div><div v-if="stockWarning" class="error-panel" role="alert">库存接口暂不可用，当前库存不能作为缺货或购买依据。</div><div v-if="catalogError" class="empty-state" role="alert"><Icon name="wifi-off"/><h3>商品暂时加载失败</h3><p>{{catalogError}}</p><button class="btn primary" @click="loadCatalog">重新加载</button></div><div v-else-if="catalogLoading" class="products" aria-busy="true"><div v-for="n in 6" :key="n" class="skeleton"></div></div><template v-else><div class="result-toolbar"><span>共 {{count}} 件商品</span><span>当前门店库存</span></div><div v-if="items.length" class="products"><ProductCard v-for="p in items" :key="p.id" :product="p" :stock-unknown="stockWarning" @unavailable="notConnected" :adding="adding" @add="addToCart"/></div><div v-else class="empty-state"><Icon name="search-x"/><h3>没有找到匹配商品</h3><p>试试其他药品名称或分类。</p><button class="btn" @click="query='';category='all';search()">清除搜索</button></div><nav v-if="count>9" class="pagination" aria-label="商品分页"><button :disabled="page<=1" @click="paginate(page-1)"><Icon name="chevron-left"/></button><span>{{page}} / {{Math.ceil(count/9)}}</span><button :disabled="page*9>=count" @click="paginate(page+1)"><Icon name="chevron-right"/></button></nav></template></section><footer class="shop-footer"><span class="wordmark">FirstSun.</span><p>请核对实际药品资料，或在药师指导下使用。</p></footer></main>
<main v-else-if="route==='detail'" class="page-container"><div class="breadcrumb"><a href="#catalog">找药购药</a><Icon name="chevron-right"/><span>商品详情</span></div><div v-if="detailLoading" class="skeleton" aria-busy="true"></div><div v-else-if="detailError" class="empty-state" role="alert"><h2>商品暂不可查看</h2><p>{{detailError}}</p><a href="#catalog" class="btn primary">返回列表</a></div><template v-else-if="detail"><div class="detail-top"><section><div class="hero-photo"><ProductCard :product="detail" image-only/></div><p class="gallery-caption">{{detail.rx?'处方包装和资料按授权范围展示':'包装图仅供识别，请以实物为准'}}</p></section><section class="detail-info"><div class="tags"><span class="tag" :class="{rx:detail.rx}">{{detail.rx?'Rx 处方药':'OTC / 商品档案'}}</span><span class="tag neutral">{{storeName}}</span></div><h1>{{detail.name}}</h1><p class="detail-spec">{{detail.specification||'规格暂未提供'}}</p><div class="detail-price"><div><span class="small">当前售价</span><span class="price"><small>¥</small>{{money(detail.price)}}</span></div><span class="stock">{{stockWarning?'库存暂不可用':`可售库存 ${detail.stock} 件`}}</span></div><dl class="details-list"><dt>生产厂家</dt><dd>{{detail.manufacturer||'商品档案暂未提供'}}</dd><dt>商品规格</dt><dd><span class="spec-option">{{detail.specification||'商品档案暂未提供'}}</span></dd></dl><div v-if="detail.rx" class="rx-notice">处方药需提交医生处方，经药师审核后按获准明细购买。</div><div class="buy-actions"><button class="btn primary" :disabled="adding||(!detail.rx&&(stockWarning||detail.stock<=0||detail.device))" @click="detail.rx?notConnected('处方申请'):addToCart(detail)">{{detail.rx?'处方申请 · 未接入':adding?'正在加购…':'加入购物车'}}</button><button class="btn" @click="askProduct"><Icon name="sparkles"/>询问 AI</button></div><p class="detail-alert">请仔细阅读药品说明书，或在药师指导下使用。</p></section></div><div class="detail-below"><section><div class="detail-tabs"><button :class="{active:infoTab==='info'}" @click="infoTab='info'">商品信息</button><button :class="{active:infoTab==='leaflet'}" @click="infoTab='leaflet'">说明书</button></div><table v-if="infoTab==='info'" class="data-table"><tbody><tr><th>通用名称</th><td>{{detail.genericName||'商品档案暂未提供'}}</td></tr><tr><th>规格</th><td>{{detail.specification||'商品档案暂未提供'}}</td></tr><tr><th>厂家</th><td>{{detail.manufacturer||'商品档案暂未提供'}}</td></tr><tr><th>批准文号</th><td>{{detail.rx?'处方资料受限':detail.approval}}</td></tr></tbody></table><div v-else class="notice-panel">{{detail.rx?'处方说明书受限，当前不公开展示。':'本批尚未接入经核验的说明书展示，请咨询药师。'}}</div></section><aside class="detail-consult"><Icon name="messages-square"/><h3>有疑问，先问一问</h3><p>AI 查询商品信息，人工服务身份独立。</p><button class="btn soft full" @click="askProduct">询问 AI 助手</button><button class="btn full" @click="notConnected('药师 / 客服咨询')">咨询药师 / 客服</button></aside></div></template></main>
<main v-else class="ai-layout"><aside class="history" :class="{'mobile-open':historyOpen}"><button class="btn new-chat" @click="newTopic" :disabled="busy||historyLoading"><Icon name="plus"/>新建对话</button><div class="between"><p class="section-label">对话历史</p><button class="icon-btn" aria-label="刷新历史" @click="loadTopics()" :disabled="historyLoading"><Icon name="refresh-cw"/></button><button class="icon-btn mobile-close" aria-label="关闭历史" @click="historyOpen=false"><Icon name="x"/></button></div><div v-if="historyLoading" class="small muted">正在读取话题…</div><div v-if="historyError" class="error-panel" role="alert">{{historyError}}<button class="btn link" @click="loadTopics()">重试</button></div><div class="history-list"><button v-for="t in topics" :key="t.id" class="history-item" :class="{active:topicId===t.id}" :disabled="historyLoading" @click="openTopic(t.id)"><Icon name="message-square"/><span>{{t.title||'新话题'}}</span></button><p v-if="!topics.length&&!historyLoading" class="small muted">{{user?'暂无历史对话':'登录后查看你的对话'}}</p><button v-if="moreTopics" class="btn link" @click="loadTopics(true)">更早话题</button></div><div class="history-bottom"><button class="btn full" @click="notConnected('药师 / 客服咨询')"><Icon name="headset"/>联系药师 / 客服</button></div></aside><section class="chat"><div class="chat-head"><div class="row"><button class="icon-btn mobile-history" aria-label="对话历史" @click="historyOpen=true"><Icon name="panel-left"/></button><span class="avatar-ai"><Icon name="sparkles"/></span><div><h1>AI 购药助手</h1><div class="status">顾客 AI · {{user?'已登录':'登录后使用'}}</div></div></div><button v-if="topicId" class="btn" :disabled="busy||historyLoading" @click="openTopic(topicId)"><Icon name="refresh-cw"/>重载话题</button><button v-else class="btn" @click="notConnected('人工咨询')">转人工</button></div><div ref="chatScroll" class="chat-scroll"><div class="chat-inner"><div class="chat-intro"><div class="eyebrow">FIRSTSUN ASSISTANT</div><h2>找药这件事，简单一点。</h2><p>告诉我药品名称，帮你查找规格、价格与库存。</p></div><div v-if="!user" class="empty-state"><h3>登录后开始咨询</h3><p>对话历史由现有会员服务保存。</p><button class="btn primary" @click="loginOpen=true">登录会员账号</button></div><template v-else><button v-if="moreTurns" class="btn link" :disabled="historyLoading" @click="openTopic(topicId,true)">加载更早消息</button><article v-for="m in messages" :key="m.id" class="message ai-turn"><div class="user-message"><div class="user-bubble">{{m.content}}</div><span class="user-avatar">我</span></div><div class="answer-heading"><span class="avatar-ai"><Icon name="sparkles"/></span>FirstSun AI<span class="tag neutral">AI 助手</span></div><div v-if="m.loading&&!m.answer" class="thinking" role="status">正在查询门店信息<span>•••</span></div><p class="answer-text" :class="{streaming:m.loading&&m.answer}">{{m.answer.replace(/\*\*([^*]+)\*\*/g,'$1')}}</p><div v-if="m.error" class="error-panel" role="alert">{{m.error}}<button v-if="m.status!=='STOPPED'&&m.status!=='PENDING'" class="btn link" :disabled="busy||historyLoading" @click="retry(m)">重试本次请求</button></div><div v-if="m.products.length" class="result-caption"><span>匹配商品 · {{m.products.length}} 款</span><span>本次查询价格 / 库存</span></div><div class="ai-products"><ProductCard v-for="p in m.products" :key="p.id" :product="p" :adding="adding" @add="addToCart" @unavailable="notConnected"/></div><div v-if="m.source||m.queriedAt" class="answer-foot">{{m.source}} · {{m.queriedAt}}</div></article><div v-if="!messages.length" class="suggestions"><button @click="send('查询板蓝根颗粒的价格和库存')" :disabled="busy||historyLoading">查询板蓝根颗粒</button><button @click="send('处方药如何购买？')" :disabled="busy||historyLoading">处方药如何购买？</button></div></template></div></div><div class="composer-wrap"><form class="composer" @submit.prevent="send()"><textarea v-model="input" aria-label="输入药品名称或问题" placeholder="输入药品名称，或说说你想了解的问题…" maxlength="500" :disabled="busy||historyLoading||!user" @keydown.enter.exact.prevent="send()"></textarea><div class="composer-tools"><span class="muted">Enter 发送 · Shift + Enter 换行</span><button v-if="busy" class="btn primary send" type="button" @click="stop"><Icon name="square"/>停止接收</button><button v-else class="btn primary send" :disabled="!input.trim()||historyLoading||!user"><Icon name="arrow-up"/>发送</button></div></form><p class="composer-note">AI 不能代替医生或药师；不提供诊断、开方或真实支付。</p></div></section><aside class="rail"><h3>购药服务</h3><p class="rail-sub">AI 查询与人工服务身份独立</p><a href="#catalog" class="service-link"><Icon name="pill"/><span class="grow">返回找药购药<span>浏览当前门店商品</span></span><Icon name="chevron-right"/></a><button class="service-link" @click="notConnected('处方申请')"><Icon name="file-check-2"/><span class="grow">处方购药<span>提交处方，经药师审核</span></span></button><button class="service-link" @click="notConnected('人工咨询')"><Icon name="headset"/><span class="grow">药师 / 客服<span>本批尚未接入</span></span></button><div class="rail-notice"><Icon name="shield-check"/><p>商品卡价格和库存来自当前查询；实际购买仍以服务端校验为准。</p></div></aside></main>
<div v-if="loginOpen||dialog" class="modal-shade" @pointerdown="backdropDown" @pointerup="backdropUp" @pointercancel="backdropCancel" @click="backdropClick" @keydown.esc="closeDialog"><section class="live-dialog" role="dialog" aria-modal="true" aria-labelledby="live-dialog-title"><div class="dialog-head"><h2 id="live-dialog-title">{{dialog?'服务尚未接入':authScreen==='register'?'会员注册':'会员登录'}}</h2><button class="icon-btn" aria-label="关闭" @click="closeDialog"><Icon name="x"/></button></div><template v-if="dialog"><p>{{dialog}}</p><button class="btn primary full" @click="closeDialog">知道了</button></template><template v-else-if="!authBusy"><RegisterGate v-if="authScreen==='register'" @logged-in="onLoggedIn"/><LoginGate v-else @logged-in="onLoggedIn"/><button v-if="localTestLogin" type="button" class="btn link full" @click="authScreen=authScreen==='register'?'login':'register'">{{authScreen==='register'?'已有账号？返回登录':'没有账号？独立注册'}}</button></template></section></div><div v-if="toastText" class="live-toast" role="status">{{toastText}}</div>
</template>
